reply:
```turtle
@prefix ea:   <http://example.org/onto/assessment#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

<http://example.org/onto/assessment>
    a owl:Ontology ;
    rdfs:label "Educational Assessment Ontology" ;
    rdfs:comment "Models classification of educational assessment as described in the source corpus, including coordinate taxonomies, axis-based definitions, and explicitly noted tensions between coordinate and subordinate classifications." .

#################################################################
# ROOT
#################################################################

ea:EducationalConstruct a owl:Class ;
    rdfs:label "EducationalConstruct" ;
    rdfs:comment "Root class unifying all concepts in the educational assessment domain." .

#################################################################
# CORE: Assessment / Test
#################################################################

ea:Assessment a owl:Class ;
    rdfs:subClassOf ea:EducationalConstruct ;
    rdfs:label "Assessment" ;
    rdfs:comment "The systematic process of documenting and using empirical data on knowledge, skill, attitudes, aptitude and beliefs to refine programs and improve student learning." .

ea:Test a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Test" ;
    skos:altLabel "Examination", "Exam", "Evaluation" ;
    rdfs:comment "Assessment is often used interchangeably with test but is not limited to tests; a test/examination is an educational assessment intended to measure knowledge, skill, aptitude, physical fitness or classification." .

ea:TestTaker a owl:Class ; rdfs:subClassOf ea:EducationalConstruct ;
    rdfs:label "TestTaker" ; skos:altLabel "Candidate", "Examinee" .

ea:Rater a owl:Class ; rdfs:subClassOf ea:EducationalConstruct ;
    rdfs:label "Rater" ; skos:altLabel "Scorer", "Examiner", "Grader" .

ea:hasTestTaker a owl:ObjectProperty ; rdfs:domain ea:Test ; rdfs:range ea:TestTaker .
ea:hasRater a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:Rater .

#################################################################
# GRANULARITY
#################################################################

ea:GranularityLevel a owl:Class ; rdfs:subClassOf ea:EducationalConstruct ;
    rdfs:label "GranularityLevel" .
ea:LearnerGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:LearningCommunityGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:CourseGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:ProgramGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:InstitutionGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:EducationalSystemGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:GranularityLevel owl:disjointUnionOf ( ea:LearnerGranularity ea:LearningCommunityGranularity
    ea:CourseGranularity ea:ProgramGranularity ea:InstitutionGranularity ea:EducationalSystemGranularity ) .

ea:hasGranularity a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:Assessment ; rdfs:range ea:GranularityLevel .

#################################################################
# AXIS 1: PURPOSE (placement / formative / summative / diagnostic)
#################################################################

ea:PurposeCategory a owl:Class ; rdfs:subClassOf ea:EducationalConstruct ; rdfs:label "PurposeCategory" .
ea:PlacementPurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:FormativePurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:SummativePurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:DiagnosticPurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:PurposeCategory owl:disjointUnionOf ( ea:PlacementPurpose ea:FormativePurpose ea:SummativePurpose ea:DiagnosticPurpose ) .

ea:hasPurpose a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:Assessment ; rdfs:range ea:PurposeCategory .

ea:PlacementAssessment a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "PlacementAssessment" ;
    skos:altLabel "pre-assessment", "initial assessment", "threshold knowledge test", "TKT" ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:PlacementPurpose ] ) ] .

ea:FormativeAssessment a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "FormativeAssessment" ;
    skos:altLabel "educative assessment", "assessment for learning", "classroom assessment", "formative evaluation", "formative feedback" ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:FormativePurpose ] ) ] .

ea:SummativeAssessment a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "SummativeAssessment" ;
    skos:altLabel "summative evaluation", "assessment of learning" ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:SummativePurpose ] ) ] .

ea:DiagnosticAssessment a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "DiagnosticAssessment" ;
    skos:altLabel "diagnostic testing" ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:DiagnosticPurpose ] ) ] ;
    rdfs:subClassOf ea:FormativeAssessment ;
    rdfs:comment "TENSION: One passage enumerates Placement, Formative, Summative and Diagnostic as four coordinate, pairwise-disjoint categories of assessment (hence the AllDisjointClasses axiom below). Another passage states 'A common form of formative assessment is diagnostic assessment', which is modeled here as rdfs:subClassOf ea:FormativeAssessment. Both claims are encoded even though they are in tension." .

[] a owl:AllDisjointClasses ;
   owl:members ( ea:PlacementAssessment ea:FormativeAssessment ea:SummativeAssessment ea:DiagnosticAssessment ) .

ea:SelfAssessment a owl:Class ;
    rdfs:subClassOf ea:DiagnosticAssessment ;
    rdfs:label "SelfAssessment" ;
    rdfs:comment "Self-assessment is a form of diagnostic assessment in which students assess themselves." .

ea:ForwardLookingAssessment a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:comment "Asks those being assessed to consider themselves in hypothetical future situations." .

ea:PerformanceBasedAssessment a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "PerformanceBasedAssessment" ;
    rdfs:comment "Similar to summative assessment in that it focuses on achievement; requires students to solve real-world problems or produce something with real-world application." .

ea:AuthenticAssessment a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "AuthenticAssessment" ;
    owl:equivalentClass ea:PerformanceBasedAssessment ;
    rdfs:comment "TENSION: A glossary passage states 'Performance assessments may also be called authentic assessments' (modeled as owl:equivalentClass with ea:PerformanceBasedAssessment). However, an earlier passage lists 'Performance-based assessments' and 'Authentic assessment' as separate, coordinate entries under 'Assessment types include', treating them as distinct named kinds." .

ea:InterimAssessment a owl:Class ; rdfs:subClassOf ea:Assessment ;
    rdfs:comment "Used to evaluate whether students are on track toward summative assessments; the corpus notes ongoing debate over whether interim assessment should be classified as formative or summative." .

ea:ScreeningAssessment a owl:Class ; rdfs:subClassOf ea:Assessment .

ea:CommonAssessment a owl:Class ; rdfs:subClassOf ea:Assessment ;
    rdfs:comment "Used across a school/department for consistency; may be formative or summative." .

ea:ContinuousAssessment a owl:Class ; rdfs:subClassOf ea:Assessment ;
    rdfs:comment "Evaluates a student's progress throughout a prescribed course; often includes formative assessment." .

ea:PortfolioAssessment a owl:Class ; rdfs:subClassOf ea:Assessment ;
    skos:altLabel "student portfolio", "e-portfolio", "digital portfolio" .

#################################################################
# AXIS 2: OBJECTIVITY (objective / subjective)
#################################################################

ea:ObjectivityCategory a owl:Class ; rdfs:subClassOf ea:EducationalConstruct .
ea:ObjectiveCategory a owl:Class ; rdfs:subClassOf ea:ObjectivityCategory .
ea:SubjectiveCategory a owl:Class ; rdfs:subClassOf ea:ObjectivityCategory .
ea:ObjectivityCategory owl:disjointUnionOf ( ea:ObjectiveCategory ea:SubjectiveCategory ) .

ea:hasObjectivity a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:Assessment ; rdfs:range ea:ObjectivityCategory .

ea:hasItemObjectivity a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:TestItem ; rdfs:range ea:ObjectivityCategory .

ea:ObjectiveAssessment a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:comment "A form of questioning that has a single correct answer." ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasObjectivity ; owl:someValuesFrom ea:ObjectiveCategory ] ) ] .

ea:SubjectiveAssessment a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:comment "A form of questioning that may have more than one correct answer." ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasObjectivity ; owl:someValuesFrom ea:SubjectiveCategory ] ) ] .

#################################################################
# AXIS 3: REFERENCING (criterion / norm / ipsative)
#################################################################

ea:ReferencingCategory a owl:Class ; rdfs:subClassOf ea:EducationalConstruct .
ea:CriterionReferencedCategory a owl:Class ; rdfs:subClassOf ea:ReferencingCategory .
ea:NormReferencedCategory a owl:Class ; rdfs:subClassOf ea:ReferencingCategory .
ea:IpsativeCategory a owl:Class ; rdfs:subClassOf ea:ReferencingCategory ; skos:altLabel "forced-choice" .
ea:ReferencingCategory owl:disjointUnionOf ( ea:CriterionReferencedCategory ea:NormReferencedCategory ea:IpsativeCategory ) .

ea:hasReferencing a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:Assessment ; rdfs:range ea:ReferencingCategory .

ea:CriterionReferencedAssessment a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    skos:altLabel "standards-based assessment" ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:CriterionReferencedCategory ] ) ] ;
    rdfs:comment "Candidates are measured against defined, objective criteria." .

ea:NormReferencedAssessment a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    skos:altLabel "normative assessment" ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:NormReferencedCategory ] ) ] ;
    rdfs:comment "Compares each test taker against other test takers; colloquially 'grading on the curve'." .

ea:IpsativeAssessment a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:IpsativeCategory ] ) ] ;
    rdfs:comment "Self-comparison either in the same domain over time, or comparative to other domains within the same student." .

[] a owl:AllDisjointClasses ;
   owl:members ( ea:CriterionReferencedAssessment ea:NormReferencedAssessment ea:IpsativeAssessment ) .

ea:CriterionReferencedTest a owl:Class ;
    rdfs:subClassOf ea:Test, ea:CriterionReferencedAssessment ;
    skos:altLabel "CRT" ;
    rdfs:comment "Most everyday quizzes and most state achievement/graduation tests are criterion-referenced." .

ea:NormReferencedTest a owl:Class ;
    rdfs:subClassOf ea:Test, ea:NormReferencedAssessment ;
    skos:altLabel "NRT" .

ea:MasteryTest a owl:Class ;
    rdfs:subClassOf ea:CriterionReferencedTest ;
    rdfs:comment "A criterion-referenced test that uses a cutscore: pass if score exceeds cutscore." .

ea:Criterion a owl:Class ; rdfs:subClassOf ea:EducationalConstruct ;
    rdfs:comment "The domain of subject matter that a criterion-referenced test is designed to assess (not the cutscore)." .

ea:hasCriterion a owl:ObjectProperty ; rdfs:domain ea:CriterionReferencedTest ; rdfs:range ea:Criterion .
ea:hasCutScore a owl:DatatypeProperty ; rdfs:domain ea:CriterionReferencedTest ; rdfs:range xsd:decimal .

#################################################################
# AXIS 4: FORMALITY (formal / informal)
#################################################################

ea:FormalityCategory a owl:Class ; rdfs:subClassOf ea:EducationalConstruct .
ea:FormalCategory a owl:Class ; rdfs:subClassOf ea:FormalityCategory .
ea:InformalCategory a owl:Class ; rdfs:subClassOf ea:FormalityCategory .
ea:FormalityCategory owl:disjointUnionOf ( ea:FormalCategory ea:InformalCategory ) .

ea:hasFormality a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:Assessment ; rdfs:range ea:FormalityCategory .

ea:FormalAssessment a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasFormality ; owl:someValuesFrom ea:FormalCategory ] ) ] ;
    rdfs:comment "Usually implies a written document and a numerical score or grade." .

ea:InformalAssessment a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasFormality ; owl:someValuesFrom ea:InformalCategory ] ) ] ;
    rdfs:comment "Does not contribute to a student's final grade." .

#################################################################
# AXIS 5: ADMINISTRATION SCOPE (internal / external)
#################################################################

ea:AdministrationScopeCategory a owl:Class ; rdfs:subClassOf ea:EducationalConstruct .
ea:InternalCategory a owl:Class ; rdfs:subClassOf ea:AdministrationScopeCategory .
ea:ExternalCategory a owl:Class ; rdfs:subClassOf ea:AdministrationScopeCategory .
ea:AdministrationScopeCategory owl:disjointUnionOf ( ea:InternalCategory ea:ExternalCategory ) .

ea:hasAdministrationScope a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:Assessment ; rdfs:range ea:AdministrationScopeCategory .

ea:InternalAssessment a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasAdministrationScope ; owl:someValuesFrom ea:InternalCategory ] ) ] ;
    rdfs:comment "Set and marked by the school/teachers." .

ea:ExternalAssessment a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasAdministrationScope ; owl:someValuesFrom ea:ExternalCategory ] ) ] ;
    rdfs:comment "Set by the governing body and marked by unbiased personnel." .

#################################################################
# AXIS 6: STANDARDIZATION (standardized / non-standardized) -- applies to Test
#################################################################

ea:StandardizationCategory a owl:Class ; rdfs:subClassOf ea:EducationalConstruct .
ea:StandardizedCategory a owl:Class ; rdfs:subClassOf ea:StandardizationCategory .
ea:NonStandardizedCategory a owl:Class ; rdfs:subClassOf ea:StandardizationCategory .
ea:StandardizationCategory owl:disjointUnionOf ( ea:StandardizedCategory ea:NonStandardizedCategory ) .

ea:hasStandardization a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:Test ; rdfs:range ea:StandardizationCategory .

ea:StandardizedTest a owl:Class ;
    rdfs:subClassOf ea:Test ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Test
        [ a owl:Restriction ; owl:onProperty ea:hasStandardization ; owl:someValuesFrom ea:StandardizedCategory ] ) ] ;
    rdfs:comment "Administered and scored in a consistent or standard manner for all test takers." .

ea:NonStandardizedTest a owl:Class ;
    rdfs:subClassOf ea:Test ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Test
        [ a owl:Restriction ; owl:onProperty ea:hasStandardization ; owl:someValuesFrom ea:NonStandardizedCategory ] ) ] ;
    rdfs:comment "Flexible in scope and format, and variable in difficulty." .

ea:TestAdministrationChange a owl:Class ; rdfs:subClassOf ea:EducationalConstruct .
ea:TestAccommodation a owl:Class ; rdfs:subClassOf ea:TestAdministrationChange ;
    rdfs:comment "Changes testing conditions to improve fairness without undermining the point of the assessment." .
ea:TestModification a owl:Class ; rdfs:subClassOf ea:TestAdministrationChange ;
    rdfs:comment "A change to testing conditions that undermines the purpose of the test (no longer standardized)." .
[] a owl:AllDisjointClasses ; owl:members ( ea:TestAccommodation ea:TestModification ) .

ea:AchievementTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest ;
    rdfs:comment "Backward-looking; measures knowledge/skills already learned." .
ea:AptitudeTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest ;
    rdfs:comment "Forward-looking; attempts to predict ability to succeed." .
ea:CollegeAdmissionsTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .
ea:InternationalComparisonTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest ;
    rdfs:comment "E.g., PISA, PIRLS, TIMSS." .
ea:PsychologicalTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest ;
    rdfs:comment "E.g., IQ tests, MMPI." .
[] a owl:AllDisjointClasses ;
   owl:members ( ea:AchievementTest ea:AptitudeTest ea:CollegeAdmissionsTest
                 ea:InternationalComparisonTest ea:PsychologicalTest ) .

#################################################################
# AXIS 7: STAKES (high-stakes / low-stakes) -- applies to Test
#################################################################

ea:StakesCategory a owl:Class ; rdfs:subClassOf ea:EducationalConstruct .
ea:HighStakesCategory a owl:Class ; rdfs:subClassOf ea:StakesCategory .
ea:LowStakesCategory a owl:Class ; rdfs:subClassOf ea:StakesCategory .
ea:StakesCategory owl:disjointUnionOf ( ea:HighStakesCategory ea:LowStakesCategory ) .

ea:hasStakes a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:Test ; rdfs:range ea:StakesCategory .

ea:HighStakesTest a owl:Class ;
    rdfs:subClassOf ea:Test ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Test
        [ a owl:Restriction ; owl:onProperty ea:hasStakes ; owl:someValuesFrom ea:HighStakesCategory ] ) ] ;
    rdfs:comment "A test with a desired reward/consequence for performance." .

ea:LowStakesTest a owl:Class ;
    rdfs:subClassOf ea:Test ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Test
        [ a owl:Restriction ; owl:onProperty ea:hasStakes ; owl:someValuesFrom ea:LowStakesCategory ] ) ] .

ea:CompetitiveExamination a owl:Class ;
    rdfs:subClassOf ea:Test ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Test
        [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:NormReferencedCategory ]
        [ a owl:Restriction ; owl:onProperty ea:hasStakes ; owl:someValuesFrom ea:HighStakesCategory ] ) ] ;
    rdfs:comment "Norm-referenced, high-stakes tests in which candidates are ranked and only the top n pass; e.g. civil service exams." .

# Explicit corpus note on cross-axis overlap (no disjointness asserted between bridge
# classes of different axes, nor across the general 'Assessment types include' list):
ea:Test rdfs:comment "The corpus explicitly states that a single test can have multiple qualities simultaneously (e.g. 'a test can be both standardized and also a high-stakes test'; the bar exam is 'a norm-referenced, standardized, summative assessment'). Therefore bridge classes defined on different axes (purpose, objectivity, referencing, formality, administration scope, standardization, stakes) are NOT asserted disjoint from one another; disjointness is only asserted within a single axis." .

#################################################################
# SCORE INTERPRETATION
#################################################################

ea:ScoreInterpretation a owl:Class ; rdfs:subClassOf ea:EducationalConstruct .
ea:NormReferencedScoreInterpretation a owl:Class ; rdfs:subClassOf ea:ScoreInterpretation .
ea:CriterionReferencedScoreInterpretation a owl:Class ; rdfs:subClassOf ea:ScoreInterpretation .
ea:ScoreInterpretation owl:disjointUnionOf ( ea:NormReferencedScoreInterpretation ea:CriterionReferencedScoreInterpretation ) .

ea:hasScoreInterpretation a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:Test ; rdfs:range ea:ScoreInterpretation .

#################################################################
# PERFORMANCE FORMAT (products vs performances)
#################################################################

ea:PerformanceFormatCategory a owl:Class ; rdfs:subClassOf ea:EducationalConstruct .
ea:ProductFormat a owl:Class ; rdfs:subClassOf ea:PerformanceFormatCategory ;
    rdfs:comment "E.g. painting, portfolio, paper, exhibition." .
ea:PerformanceEventFormat a owl:Class ; rdfs:subClassOf ea:PerformanceFormatCategory ;
    rdfs:comment "E.g. speech, athletic skill, musical recital, reading." .
ea:PerformanceFormatCategory owl:disjointUnionOf ( ea:ProductFormat ea:PerformanceEventFormat ) .

ea:hasPerformanceFormat a owl:ObjectProperty ;
    rdfs:domain ea:PerformanceBasedAssessment ; rdfs:range ea:PerformanceFormatCategory .

ea:PerformanceTest a owl:Class ;
    rdfs:subClassOf ea:Test ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Test ea:PerformanceBasedAssessment ) ] ;
    skos:altLabel "work sample" ;
    rdfs:comment "Requires an examinee to actually perform a task or activity rather than simply answering questions about it." .

#################################################################
# TEST ITEMS
#################################################################

ea:TestItem a owl:Class ; rdfs:subClassOf ea:EducationalConstruct ;
    skos:altLabel "question" .

ea:isItemOf a owl:ObjectProperty ; rdfs:domain ea:TestItem ; rdfs:range ea:Test ;
    owl:inverseOf ea:hasItem .
ea:hasItem a owl:ObjectProperty ; rdfs:domain ea:Test ; rdfs:range ea:TestItem .

ea:ObjectiveItem a owl:Class ;
    rdfs:subClassOf ea:TestItem ;
    owl:equivalentClass [ owl:intersectionOf ( ea:TestItem
        [ a owl:Restriction ; owl:onProperty ea:hasItemObjectivity ; owl:someValuesFrom ea:ObjectiveCategory ] ) ] .

ea:SubjectiveItem a owl:Class ;
    rdfs:subClassOf ea:TestItem ;
    owl:equivalentClass [ owl:intersectionOf ( ea:TestItem
        [ a owl:Restriction ; owl:onProperty ea:hasItemObjectivity ; owl:someValuesFrom ea:SubjectiveCategory ] ) ] .

[] a owl:AllDisjointClasses ; owl:members ( ea:ObjectiveItem ea:SubjectiveItem ) .

ea:TrueFalseItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem .
ea:MultipleChoiceItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem ; skos:altLabel "MCQ" .
ea:MultipleResponseItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem .
ea:MatchingItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem .
[] a owl:AllDisjointClasses ;
   owl:members ( ea:TrueFalseItem ea:MultipleChoiceItem ea:MultipleResponseItem ea:MatchingItem ) .

ea:ExtendedResponseItem a owl:Class ; rdfs:subClassOf ea:SubjectiveItem .
ea:EssayItem a owl:Class ; rdfs:subClassOf ea:SubjectiveItem ;
    skos:altLabel "free response question", "FRQ", "essay question" .
[] a owl:AllDisjointClasses ; owl:members ( ea:ExtendedResponseItem ea:EssayItem ) .

ea:ShortAnswerItem a owl:Class ; rdfs:subClassOf ea:SubjectiveItem .
ea:FillInTheBlankItem a owl:Class ; rdfs:subClassOf ea:TestItem .

ea:AnswerOption a owl:Class ; rdfs:subClassOf ea:EducationalConstruct .

ea:hasOption a owl:ObjectProperty ; rdfs:domain ea:TestItem ; rdfs:range ea:AnswerOption .
ea:hasKey a owl:ObjectProperty ; rdfs:subPropertyOf ea:hasOption ;
    rdfs:domain ea:TestItem ; rdfs:range ea:AnswerOption ;
    rdfs:comment "The option that is the correct answer." .
ea:hasDistractor a owl:ObjectProperty ; rdfs:subPropertyOf ea:hasOption ;
    rdfs:domain ea:TestItem ; rdfs:range ea:AnswerOption ;
    rdfs:comment "An incorrect option." .
ea:hasStemText a owl:DatatypeProperty ; rdfs:domain ea:TestItem ; rdfs:range xsd:string .

ea:MultipleChoiceItem rdfs:subClassOf
    [ a owl:Restriction ; owl:onProperty ea:hasKey ; owl:onClass ea:AnswerOption ;
      owl:qualifiedCardinality "1"^^xsd:nonNegativeInteger ] ;
    rdfs:comment "Only one answer may be keyed as correct." .

ea:MultipleResponseItem rdfs:subClassOf
    [ a owl:Restriction ; owl:onProperty ea:hasKey ; owl:onClass ea:AnswerOption ;
      owl:minQualifiedCardinality "2"^^xsd:nonNegativeInteger ] ;
    owl:disjointWith ea:MultipleChoiceItem ;
    rdfs:comment "More than one answer may be keyed as correct, contrasting with MultipleChoiceItem." .

#################################################################
# PARTICULAR TEST OCCASIONS
#################################################################

ea:Quiz a owl:Class ; rdfs:subClassOf ea:Test, ea:FormativeAssessment ;
    rdfs:comment "A brief assessment, usually provided as a formative assessment." .

ea:MidtermExamination a owl:Class ;
    rdfs:subClassOf ea:Test ;
    rdfs:subClassOf [ owl:unionOf ( ea:FormativeAssessment ea:SummativeAssessment ) ] ;
    skos:altLabel "midterm exam" ;
    rdfs:comment "An exam given near the middle of an academic grading term; stated to be 'a type of formative or summative assessment'." .

ea:FinalExamination a owl:Class ;
    rdfs:subClassOf ea:Test, ea:SummativeAssessment ;
    skos:altLabel "final exam", "final" .

ea:WrittenTest a owl:Class ; rdfs:subClassOf ea:Test .

#################################################################
# RUBRIC AND GRADING
#################################################################

ea:Rubric a owl:Class ; rdfs:subClassOf ea:EducationalConstruct ;
    skos:altLabel "scoring guide" .

ea:hasRubric a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:Rubric .

ea:HolisticRubric a owl:Class ; rdfs:subClassOf ea:Rubric .
ea:AnalyticRubric a owl:Class ; rdfs:subClassOf ea:Rubric .
ea:Rubric owl:disjointUnionOf ( ea:HolisticRubric ea:AnalyticRubric ) .

ea:DevelopmentalRubric a owl:Class ;
    rdfs:subClassOf ea:AnalyticRubric ;
    rdfs:comment "TENSION: One passage lists holistic, analytic, and developmental rubrics as three coordinate kinds (hence the AllDisjointClasses axiom below). The same passage immediately clarifies that 'Developmental rubrics [are] a subset of analytical rubrics', modeled here as rdfs:subClassOf ea:AnalyticRubric. Both claims are encoded." .

[] a owl:AllDisjointClasses ;
   owl:members ( ea:HolisticRubric ea:AnalyticRubric ea:DevelopmentalRubric ) .

ea:GradingApproach a owl:Class ; rdfs:subClassOf ea:EducationalConstruct .
ea:HolisticGrading a owl:Class ; rdfs:subClassOf ea:GradingApproach ; skos:altLabel "holistic scoring" .
ea:AnalyticGrading a owl:Class ; rdfs:subClassOf ea:GradingApproach ; skos:altLabel "analytic grading" .
ea:GradingApproach owl:disjointUnionOf ( ea:HolisticGrading ea:AnalyticGrading ) .

ea:TraitInformedScoring a owl:Class ; rdfs:subClassOf ea:GradingApproach ;
    rdfs:comment "Trains raters to score against a rubric with multiple traits; 'comes close to' analytic scoring but 'remains holistic at heart'." .

#################################################################
# RELIABILITY
#################################################################

ea:Reliability a owl:Class ; rdfs:subClassOf ea:EducationalConstruct ;
    rdfs:comment "The consistency of an assessment; freedom of a measure from measurement error." .

ea:hasReliability a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:Reliability .
ea:hasReliabilityCoefficient a owl:DatatypeProperty ; rdfs:domain ea:Reliability ; rdfs:range xsd:decimal ;
    rdfs:comment "Ranges from 0.00 (much error) to 1.00 (no error)." .

ea:InterRaterReliability a owl:Class ; rdfs:subClassOf ea:Reliability .
ea:TestRetestReliability a owl:Class ; rdfs:subClassOf ea:Reliability ; skos:altLabel "repeatability" .
ea:InterMethodReliability a owl:Class ; rdfs:subClassOf ea:Reliability .
ea:InternalConsistencyReliability a owl:Class ; rdfs:subClassOf ea:Reliability .
[] a owl:AllDisjointClasses ;
   owl:members ( ea:InterRaterReliability ea:TestRetestReliability ea:InterMethodReliability ea:InternalConsistencyReliability ) .

ea:IntraRaterReliability a owl:Class ; rdfs:subClassOf ea:TestRetestReliability .
ea:ParallelFormsReliability a owl:Class ; rdfs:subClassOf ea:InterMethodReliability ;
    skos:altLabel "alternate-forms reliability" .
ea:SplitHalfReliability a owl:Class ; rdfs:subClassOf ea:InternalConsistencyReliability .

ea:ReliabilityFactorType a owl:Class ; rdfs:subClassOf ea:EducationalConstruct ;
