    rdfs:comment "X = T + E (Classical Test Theory)." .
ea:TrueScore a owl:Class ; rdfs:subClassOf ea:Score, ea:ScoreComponent ;
    rdfs:comment "The replicable feature of the concept being measured." .
ea:MeasurementError a owl:Class ; rdfs:subClassOf ea:ScoreComponent .
ea:RandomError a owl:Class ; rdfs:subClassOf ea:MeasurementError .
ea:SystematicError a owl:Class ; rdfs:subClassOf ea:MeasurementError .
ea:MeasurementError owl:disjointUnionOf ( ea:RandomError ea:SystematicError ) .

ea:hasScoreComponent a owl:ObjectProperty ; rdfs:domain ea:ObservedScore ; rdfs:range ea:ScoreComponent .
