#################################################################
# VALIDITY
#################################################################

ea:Validity a owl:Class ; rdfs:subClassOf ea:EducationalConstruct ;
    rdfs:comment "The degree to which an assessment measures what it is intended to measure." .

ea:hasValidity a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:Validity .
