ea:ContentValidity a owl:Class ; rdfs:subClassOf ea:Validity ; skos:altLabel "logical validity" .
ea:CriterionValidity a owl:Class ; rdfs:subClassOf ea:Validity ; skos:altLabel "criterion-related validity" .
ea:ConstructValidity a owl:Class ; rdfs:subClassOf ea:Validity .
ea:ConsequentialValidity a owl:Class ; rdfs:subClassOf ea:Validity .
ea:FaceValidity a owl:Class ; rdfs:subClassOf ea:Validity .

[] a owl:AllDisjointClasses ;
   owl:members ( ea:ContentValidity ea:CriterionValidity ea:ConstructValidity ea:ConsequentialValidity ea:FaceValidity ) .

ea:ContentValidity rdfs:subClassOf ea:ConstructValidity .
ea:CriterionValidity rdfs:subClassOf ea:ConstructValidity .
ea:ConsequentialValidity rdfs:subClassOf ea:ConstructValidity .
ea:FaceValidity rdfs:subClassOf ea:ConstructValidity .
ea:ConstructValidity rdfs:comment "TENSION: One passage ('Validity of an assessment is generally gauged through examination of evidence in the following categories: Content validity, Criterion validity, Construct validity... Others are: consequential validity, face validity') presents these as a coordinate, disjoint list (see AllDisjointClasses above). Another passage states construct validity 'subsumes all other types of validity', modeled by making Content, Criterion, Consequential and Face validity all rdfs:subClassOf ea:ConstructValidity. Both claims are encoded." .

ea:ConcurrentValidity a owl:Class ; rdfs:subClassOf ea:CriterionValidity ;
    rdfs:comment "Compares the test to an outcome measured at the same time." .
ea:PredictiveValidity a owl:Class ; rdfs:subClassOf ea:CriterionValidity ;
    rdfs:comment "Compares the test to an outcome measured at a later time. Also used, in a distinct sense ('predictive' vs 'subject-matter' validity), to mean validity for predicting workplace performance." .
[] a owl:AllDisjointClasses ; owl:members ( ea:ConcurrentValidity ea:PredictiveValidity ) .

ea:SubjectMatterValidity a owl:Class ; rdfs:subClassOf ea:Validity ;
    rdfs:comment "Predicts the score a student would get on a similar test with different questions; contrasted with predictive validity, which predicts workplace performance." .

ea:ConvergentValidity a owl:Class ; rdfs:subClassOf ea:ConstructValidity ;
    rdfs:comment "Degree to which two measures of theoretically related constructs are in fact related." .
ea:DiscriminantValidity a owl:Class ; rdfs:subClassOf ea:ConstructValidity ;
    skos:altLabel "divergent validity" ;
    rdfs:comment "Tests whether concepts/measurements that should be unrelated are in fact unrelated." .
[] a owl:AllDisjointClasses ; owl:members ( ea:ConvergentValidity ea:DiscriminantValidity ) .

#################################################################
